import { Injectable } from '@nestjs/common';
import { spawn } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

@Injectable()
export class AppService {
  async compile(fileName: string, fileContent: string): Promise<{ hasError: boolean; compilerError: string | null }> {
    // Use a secure temporary directory
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'compiler-'));

    try {
      // Sanitize and validate the fileName
      if (!/^[a-zA-Z0-9_\-]+\.(ts|cpp)$/.test(fileName)) {
        throw new Error('Invalid file name');
      }

      const filePath = path.join(tempDir, fileName);
      fs.writeFileSync(filePath, fileContent, { mode: 0o600 }); // Restrictive permissions

      let command: string;
      let args: string[];

      if (fileName.endsWith('.ts')) {
        command = 'tsc';
        args = [filePath];
      } else if (fileName.endsWith('.cpp')) {
        command = 'g++';
        args = [filePath, '-o', `${filePath}.out`];
      } else {
        throw new Error('Unsupported file type');
      }

      await this.executeCommand(command, args);
      return { hasError: false, compilerError: null };
    } catch (error) {
      // Sanitize error messages
      const sanitizedError = error.message.split('\n')[0];
      return { hasError: true, compilerError: sanitizedError };
    } finally {
      // Clean up temporary files
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
  }

  private executeCommand(command: string, args: string[]): Promise<void> {
    return new Promise((resolve, reject) => {
      const process = spawn(command, args);

      process.on('error', (error) => {
        reject(new Error(`Failed to start process: ${error.message}`));
      });

      process.stderr.on('data', (data) => {
        reject(new Error(data.toString()));
      });

      process.on('close', (code) => {
        if (code !== 0) {
          reject(new Error(`Process exited with code: ${code}`));
        } else {
          resolve();
        }
      });
    });
  }
}

