import { Controller, Post, UploadedFiles, Body, Res, HttpStatus, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';
import { Response } from 'express';
import { FilesInterceptor } from '@nestjs/platform-express';
import { UseInterceptors } from '@nestjs/common';
import { diskStorage } from 'multer';
import { v4 as uuidv4 } from 'uuid';
import * as path from 'path';
import * as fs from 'fs';
import * as fileType from 'file-type';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('create-gif')
  @UseInterceptors(FilesInterceptor('images', 10, {
    storage: diskStorage({
      destination: './uploads',
      filename: (req, file, cb) => {
        const filename: string = uuidv4();
        const extension: string = path.extname(file.originalname);
        cb(null, `${filename}${extension}`);
      },
    }),
    fileFilter: async (req, file, cb) => {
      const buffer = await file.buffer;
      const type = await fileType.fromBuffer(buffer);
      if (!type || !type.mime.startsWith('image/')) {
        return cb(new BadRequestException('Only image files are allowed!'), false);
      }
      cb(null, true);
    },
  }))
  async createGif(
    @UploadedFiles() files: Express.Multer.File[],
    @Body('targetSize') targetSize: string,
    @Body('delay') delay: number,
    @Body('appendReverted') appendReverted: boolean,
    @Res() res: Response,
  ) {
    if (!files || files.length === 0) {
      return res.status(HttpStatus.BAD_REQUEST).json({ error: 'No images uploaded' });
    }

    // Validate inputs
    if (!/^\d+x\d+$/.test(targetSize)) {
      return res.status(HttpStatus.BAD_REQUEST).json({ error: 'Invalid targetSize format' });
    }
    if (isNaN(delay) || delay <= 0) {
      return res.status(HttpStatus.BAD_REQUEST).json({ error: 'Invalid delay value' });
    }

    try {
      const gifBuffer = await this.appService.createGif(files, targetSize, delay, appendReverted);
      res.setHeader('Content-Type', 'image/gif');
      res.send(gifBuffer);
    } catch (error) {
      res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({ error: 'Failed to create GIF' });
    }
  }
}

