// src/app.service.ts
import { Injectable } from '@nestjs/common';
import { execFile } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';

const execFileAsync = promisify(execFile);

@Injectable()
export class AppService {
  async createGif(files: Express.Multer.File[], targetSize: string, delay: number, appendReverted: boolean): Promise<Buffer> {
    const filePaths = files.map(file => file.path);
    const outputFilePath = path.join('./uploads', `output-${Date.now()}.gif`);

    const args = ['-delay', delay.toString(), '-resize', targetSize, ...filePaths];

    if (appendReverted) {
      args.push(...filePaths.reverse());
    }

    args.push(outputFilePath);

    await execFileAsync('convert', args);

    const gifBuffer = fs.readFileSync(outputFilePath);

    // Clean up temporary files asynchronously
    filePaths.forEach(filePath => fs.unlink(filePath, err => {
      if (err) console.error(`Failed to delete file: ${filePath}`, err);
    }));
    fs.unlink(outputFilePath, err => {
      if (err) console.error(`Failed to delete file: ${outputFilePath}`, err);
    });

    return gifBuffer;
  }
}

