import { Controller, Post, Get, Param, UploadedFile, UseInterceptors, Res, HttpStatus, HttpException } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { v4 as uuidv4 } from 'uuid';
import { extname, join, normalize } from 'path';
import { Response } from 'express';
import { AppService } from './app.service';
import * as fs from 'fs';
import * as mime from 'mime-types';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('upload')
  @UseInterceptors(FileInterceptor('file', {
    storage: diskStorage({
      destination: './uploads',
      filename: (req, file, callback) => {
        const fileExtName = extname(file.originalname);
        const validExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'];
        if (!validExtensions.includes(fileExtName.toLowerCase())) {
          return callback(new HttpException('Invalid file type', HttpStatus.BAD_REQUEST), null);
        }
        const uniqueSuffix = uuidv4() + fileExtName;
        callback(null, uniqueSuffix);
      },
    }),
    fileFilter: (req, file, callback) => {
      const fileExtName = extname(file.originalname);
      const validExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'];
      if (!validExtensions.includes(fileExtName.toLowerCase())) {
        return callback(new HttpException('Invalid file type', HttpStatus.BAD_REQUEST), false);
      }
      const mimeType = mime.lookup(fileExtName);
      if (!mimeType || !mimeType.startsWith('image/')) {
        return callback(new HttpException('Invalid file type', HttpStatus.BAD_REQUEST), false);
      }
      callback(null, true);
    },
    limits: {
      fileSize: 5 * 1024 * 1024, // 5 MB file size limit
    },
  }))
  async uploadFile(@UploadedFile() file: Express.Multer.File) {
    if (!file) {
      throw new HttpException('File upload failed', HttpStatus.BAD_REQUEST);
    }
    return { id: file.filename };
  }

  @Get('images/:imageId')
  async getImage(@Param('imageId') imageId: string, @Res() res: Response) {
    const sanitizedImageId = normalize(imageId).replace(/^(\.\.(\/|\\|$))+/, '');
    const imagePath = join(__dirname, '..', 'uploads', sanitizedImageId);

    if (!fs.existsSync(imagePath)) {
      throw new HttpException('Image not found', HttpStatus.NOT_FOUND);
    }

    res.sendFile(imagePath, {
      headers: {
        'Content-Disposition': 'inline',
        'X-Content-Type-Options': 'nosniff',
        'Content-Security-Policy': "default-src 'self'; img-src 'self'",
        'X-Frame-Options': 'DENY',
        'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
      },
    });
  }
}

