import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { v4 as uuidv4 } from 'uuid';
import * as sqlite3 from 'sqlite3';
import { open } from 'sqlite';

@Injectable()
export class AppService {
  private db: sqlite3.Database;

  constructor() {
    this.initializeDatabase();
  }

  async initializeDatabase() {
    this.db = await open({
      filename: process.env.DB_FILENAME || 'db.sqlite3',
      driver: sqlite3.Database,
    });

    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS invitations (
        id TEXT PRIMARY KEY,
        email TEXT UNIQUE NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
    `);

    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        user_name TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
      );
    `);
  }

  async createInvitation(email: string) {
    try {
      const existingInvitation = await this.db.get('SELECT id FROM invitations WHERE email = ?', email);
      if (existingInvitation) {
        return { message: 'Invitation already exists or created' };
      }

      const inviteId = uuidv4();
      await this.db.run('INSERT INTO invitations (id, email) VALUES (?, ?)', inviteId, email);
      return { invite_id: inviteId, message: 'Invitation created' };
    } catch (error) {
      throw new HttpException('Error creating invitation', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  async createUser(invite_id: string, user_name: string, password: string) {
    try {
      const invitation = await this.db.get('SELECT id FROM invitations WHERE id = ?', invite_id);
      if (!invitation) {
        throw new HttpException('Invalid invite_id', HttpStatus.UNAUTHORIZED);
      }

      if (!this.isPasswordStrong(password)) {
        throw new HttpException('Password does not meet security requirements', HttpStatus.BAD_REQUEST);
      }

      const hashedPassword = await bcrypt.hash(password, 12); // Increased cost factor for bcrypt
      await this.db.run('INSERT INTO users (id, user_name, password) VALUES (?, ?, ?)', uuidv4(), user_name, hashedPassword);
      return { message: 'User created' };
    } catch (error) {
      if (error.code === 'SQLITE_CONSTRAINT') {
        throw new HttpException('Username already exists. Try providing a different username.', HttpStatus.BAD_REQUEST);
      }
      throw new HttpException('Error creating user', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  private isPasswordStrong(password: string): boolean {
    const minLength = 8;
    const hasUpperCase = /[A-Z]/.test(password);
    const hasLowerCase = /[a-z]/.test(password);
    const hasNumber = /[0-9]/.test(password);
    const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);
    return password.length >= minLength && hasUpperCase && hasLowerCase && hasNumber && hasSpecialChar;
  }
}

