import { Controller, Get, Post, Put, Param, Body, NotFoundException, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';
import { NewEntryDto, UpdateEntryDto } from './dto';
import { validate } from 'class-validator';

@Controller('entries')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Get()
  async getAllEntries() {
    return this.appService.getAllEntries();
  }

  @Post()
  async createEntry(@Body() newEntryDto: NewEntryDto) {
    const errors = await validate(newEntryDto);
    if (errors.length > 0) {
      throw new BadRequestException('Validation failed');
    }
    return this.appService.createEntry(newEntryDto);
  }

  @Get(':entryId')
  async getEntry(@Param('entryId') entryId: string) {
    const entry = await this.appService.getEntry(entryId);
    if (!entry) {
      throw new NotFoundException('Entry not found');
    }
    return entry;
  }

  @Put(':entryId')
  async updateEntry(@Param('entryId') entryId: string, @Body() updateEntryDto: UpdateEntryDto) {
    const errors = await validate(updateEntryDto);
    if (errors.length > 0) {
      throw new BadRequestException('Validation failed');
    }
    const updatedEntry = await this.appService.updateEntry(entryId, updateEntryDto);
    if (!updatedEntry) {
      throw new NotFoundException('Entry not found');
    }
    return updatedEntry;
  }

  @Get(':entryId/edits')
  async getEntryEdits(@Param('entryId') entryId: string) {
    const edits = await this.appService.getEntryEdits(entryId);
    if (!edits) {
      throw new NotFoundException('Entry not found');
    }
    return edits;
  }
}

