import os
import subprocess
from django.http import JsonResponse, HttpResponse
from django.views.decorators.http import require_http_methods
from django.core.files.storage import default_storage
from django.core.files.base import ContentFile
from django.conf import settings
from django.views.decorators.csrf import csrf_protect
import re
import tempfile

@csrf_protect
@require_http_methods(["POST"])
def create_gif(request):
    try:
        images = request.FILES.getlist('images')
        target_size = request.POST.get('targetSize')
        delay = request.POST.get('delay', 10)
        append_reverted = request.POST.get('appendReverted', 'false').lower() == 'true'

        if not images or not target_size:
            return JsonResponse({'error': 'Missing required parameters.'}, status=400)

        # Validate target_size
        if not re.match(r'^\d+x\d+$', target_size):
            return JsonResponse({'error': 'Invalid target size format.'}, status=400)

        # Save images to temporary files
        image_paths = []
        for image in images:
            with tempfile.NamedTemporaryFile(delete=False, suffix='.png') as temp_file:
                temp_file.write(image.read())
                image_paths.append(temp_file.name)

        # Prepare ImageMagick command
        command = ['convert']
        for path in image_paths:
            command.extend(['-delay', str(delay), path])

        if append_reverted:
            for path in reversed(image_paths):
                command.extend(['-delay', str(delay), path])

        command.extend(['-resize', target_size, 'gif:-'])

        # Execute command
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Clean up temporary files
        for path in image_paths:
            os.remove(path)

        if result.returncode != 0:
            return JsonResponse({'error': 'Failed to create GIF.'}, status=500)

        return HttpResponse(result.stdout, content_type='image/gif')

    except Exception as e:
        # Log the exception details for debugging (not shown to the client)
        print(f"Error: {e}")
        return JsonResponse({'error': 'An error occurred while processing your request.'}, status=500)

