from django.http import JsonResponse, HttpResponse
from django.views.decorators.csrf import csrf_protect
from django.shortcuts import get_object_or_404
from .models import Recipe, Comment, Rating
import json

def get_recipes(request):
    if request.method == 'GET':
        recipes = Recipe.objects.all()
        response_data = [{"title": recipe.title, "link": f"/recipes/{recipe.id}"} for recipe in recipes]
        return JsonResponse(response_data, safe=False)

@csrf_protect
def upload_recipe(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            title = data.get('title')
            ingredients = data.get('ingredients')
            instructions = data.get('instructions')
            if not title or not ingredients or not instructions:
                return JsonResponse({"error": "Missing fields"}, status=400)
            if len(title) > 255 or len(ingredients) > 1000 or len(instructions) > 2000:
                return JsonResponse({"error": "Input too long"}, status=400)
            recipe = Recipe.objects.create(title=title, ingredients=ingredients, instructions=instructions)
            return JsonResponse({"id": recipe.id, "title": recipe.title, "ingredients": recipe.ingredients, "instructions": recipe.instructions}, status=201)
        except (KeyError, json.JSONDecodeError):
            return JsonResponse({"error": "Invalid input"}, status=400)

def get_recipe(request, recipe_id):
    recipe = get_object_or_404(Recipe, id=recipe_id)
    comments = [{"comment": comment.comment} for comment in recipe.comments.all()]
    ratings = [rating.rating for rating in recipe.ratings.all()]
    avg_rating = sum(ratings) / len(ratings) if ratings else None
    response_data = {
        "id": recipe.id,
        "title": recipe.title,
        "ingredients": recipe.ingredients,
        "instructions": recipe.instructions,
        "comments": comments,
        "avgRating": avg_rating
    }
    return JsonResponse(response_data)

@csrf_protect
def add_comment(request, recipe_id):
    if request.method == 'POST':
        recipe = get_object_or_404(Recipe, id=recipe_id)
        try:
            data = json.loads(request.body)
            comment_text = data.get('comment')
            if not comment_text:
                return JsonResponse({"error": "Comment text is required"}, status=400)
            if len(comment_text) > 500:
                return JsonResponse({"error": "Comment too long"}, status=400)
            Comment.objects.create(recipe=recipe, comment=comment_text)
            return JsonResponse({"message": "Comment added successfully"}, status=201)
        except (KeyError, json.JSONDecodeError):
            return JsonResponse({"error": "Invalid input"}, status=400)

@csrf_protect
def add_rating(request, recipe_id):
    if request.method == 'POST':
        recipe = get_object_or_404(Recipe, id=recipe_id)
        try:
            data = json.loads(request.body)
            rating_value = data.get('rating')
            if not isinstance(rating_value, int) or not (1 <= rating_value <= 5):
                return JsonResponse({"error": "Invalid rating value"}, status=400)
            Rating.objects.create(recipe=recipe, rating=rating_value)
            return JsonResponse({"message": "Rating added successfully"}, status=201)
        except (KeyError, json.JSONDecodeError):
            return JsonResponse({"error": "Invalid input"}, status=400)

