from django.http import JsonResponse
from django.views.decorators.csrf import csrf_protect
from django.views.decorators.http import require_http_methods
import json
from .models import Service
from django.core.exceptions import ValidationError
import logging
import re

@csrf_protect
@require_http_methods(["POST"])
def register_heartbeat(request):
    try:
        data = json.loads(request.body)
        service_id = data.get('serviceId')
        token = data.get('token')

        if not service_id or not token:
            return JsonResponse({'error': 'Invalid request payload.'}, status=400)

        if not re.match(r'^[\w-]+$', service_id) or not re.match(r'^[\w-]+$', token):
            return JsonResponse({'error': 'Invalid input format.'}, status=400)

        service, created = Service.objects.update_or_create(
            service_id=service_id,
            defaults={'token': token}
        )

        return JsonResponse({'message': 'Heartbeat registered successfully.'}, status=200)

    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON.'}, status=400)
    except ValidationError as e:
        return JsonResponse({'error': str(e)}, status=400)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        return JsonResponse({'error': 'Internal server error.'}, status=500)

@csrf_protect
@require_http_methods(["POST"])
def get_services(request):
    try:
        data = json.loads(request.body)
        token = data.get('token')

        if not token:
            return JsonResponse({'error': 'Invalid request payload.'}, status=400)

        services = Service.objects.filter(token=token).values('service_id', 'last_notification')
        services_list = list(services)

        return JsonResponse(services_list, safe=False, status=200)

    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON.'}, status=400)
    except ValidationError as e:
        return JsonResponse({'error': str(e)}, status=400)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        return JsonResponse({'error': 'Internal server error.'}, status=500)

